//go:build ignore

package main

import (
	"encoding/hex"
	"fmt"
	"log"

	"github.com/meta-node-blockchain/meta-node/pkg/state"
)

func main() {
	hexVal := ""
	b, err := hex.DecodeString(hexVal)
	if err != nil {
		log.Fatalf("Decode failed: %v", err)
	}

	as := &state.AccountState{}
	err = as.Unmarshal(b)
	if err != nil {
		log.Fatalf("Unmarshal failed: %v", err)
	}

	fmt.Printf("AccountState details:\n%s\n", as.String())
}
